using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Accounts;using Namaa.Api.Extensions;using Namaa.Application.Accounts.Commands.CreateAccount;using Namaa.Application.Accounts.Commands.UpdateAccount;using Namaa.Application.Accounts.Queries.GetAccountById;using Namaa.Application.Accounts.Queries.GetAccounts;namespace Namaa.Api.Controllers;[ApiController][Route("api/accounts")]public sealed class AccountsController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreateAccountRequest request,CancellationToken cancellationToken){var result=await sender.Send(new CreateAccountCommand(request.AccountCode,request.AccountName,request.AccountType,request.IsPostingAllowed,request.Description,request.ParentAccountId),cancellationToken);return result.IsFailure?result.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=result.Value.Id},result.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetAccountsQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetAccountByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdateAccountRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdateAccountCommand(id,request.AccountName,request.AccountType,request.IsPostingAllowed,request.Description,request.ParentAccountId),cancellationToken)).ToActionResult(this);}
